#include <openssl/bio.h>
#include <openssl/err.h>
#include <openssl/mem.h>
#include <openssl/pem.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

int test_pem(const char *desc, const unsigned char *data, size_t len) {
    char *name = NULL, *header = NULL;
    unsigned char *pem_data = NULL;
    long pem_len;

    BIO *bio = BIO_new_mem_buf(data, len);
    int ret = PEM_read_bio(bio, &name, &header, &pem_data, &pem_len);

    if (ret == 1) {
        printf("OK: %s (len=%ld)\n", desc, pem_len);
        OPENSSL_free(name);
        OPENSSL_free(header);
        OPENSSL_free(pem_data);
    } else {
        printf("ERR: %s\n", desc);
    }

    BIO_free(bio);
    ERR_clear_error();
    return ret;
}

int main() {
    // Test 1: Normal PEM with header and data
    test_pem("normal", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "Proc-Type: 4,ENCRYPTED\n"
        "DEK-Info: AES-128-CBC,0123456789ABCDEF\n"
        "\n"
        "YWJjZGVmZ2hpamtsbW5vcA==\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 2: nohead=1 with valid base64 header
    test_pem("nohead_base64", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "abcd\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 3: nohead=1 with empty header
    test_pem("nohead_empty", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 4: nohead=1 with multiple valid base64 lines
    test_pem("nohead_multi", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "abcd\n"
        "efgh\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 5: Normal PEM with short data line
    test_pem("short_data", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "\n"
        "YWJj\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 6: PEM with binary data
    {
        unsigned char bin[] = {
            '-','-','-','-','-','B','E','G','I','N',' ','C','E','R','T','I','F','I','C','A','T','E','-','-','-','-','-','\n',
            0x00, 0x01, 0x02, '\n',
            '-','-','-','-','-','E','N','D',' ','C','E','R','T','I','F','I','C','A','T','E','-','-','-','-','-','\n'
        };
        test_pem("binary_header", bin, sizeof(bin));
    }

    // Test 7: PEM with no newline at end
    test_pem("no_newline", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "abcd\n"
        "-----END CERTIFICATE-----", 0);

    // Test 8: PEM with only BEGIN and END, no header, no data
    test_pem("minimal", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 9: PEM with header that has no DEK-Info
    test_pem("no_dek", (const unsigned char *)
        "-----BEGIN CERTIFICATE-----\n"
        "Proc-Type: 4,ENCRYPTED\n"
        "\n"
        "YWJjZGVmZ2hpamtsbW5vcA==\n"
        "-----END CERTIFICATE-----\n", 0);

    // Test 10: PEM with very long header line
    {
        char buf[512];
        int pos = 0;
        pos += sprintf(buf + pos, "-----BEGIN CERTIFICATE-----\n");
        memset(buf + pos, 'A', 200);
        pos += 200;
        pos += sprintf(buf + pos, "\n");
        pos += sprintf(buf + pos, "-----END CERTIFICATE-----\n");
        test_pem("long_header", (const unsigned char *)buf, pos);
    }

    printf("All tests done.\n");
    return 0;
}
